/* Static SVG generated by the same Fourier model and renderer as the canvas. */
import { writeFileSync } from 'node:fs'
import { createFourierHat } from '../assets/js/decorations/fourier-hat.js'

const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
const number = value => Number(value.toFixed(3))
const elements = []
const stack = []
let path = [], dash = []
const context = {
  globalAlpha: 1, lineWidth: 1, fillStyle: 'none', strokeStyle: 'none', textAlign: 'left', font: '12px serif',
  beginPath() { path = [] },
  moveTo(x, y) { path.push(`M${number(x)} ${number(y)}`) },
  lineTo(x, y) { path.push(`L${number(x)} ${number(y)}`) },
  arc(x, y, radius) {
    path.push(`M${number(x + radius)} ${number(y)}A${number(radius)} ${number(radius)} 0 1 0 ${number(x - radius)} ${number(y)}A${number(radius)} ${number(radius)} 0 1 0 ${number(x + radius)} ${number(y)}`)
  },
  setLineDash(value) { dash = value },
  stroke() {
    const dashAttribute = dash.length ? ` stroke-dasharray="${dash.join(' ')}"` : ''
    elements.push(`<path d="${path.join('')}" fill="none" stroke="${escape(this.strokeStyle)}" stroke-width="${number(this.lineWidth)}" opacity="${number(this.globalAlpha)}"${dashAttribute}/>`)
  },
  fill() { elements.push(`<path d="${path.join('')}" fill="${escape(this.fillStyle)}" opacity="${number(this.globalAlpha)}"/>`) },
  fillText(text, x, y) {
    const anchor = this.textAlign === 'center' ? 'middle' : this.textAlign === 'right' ? 'end' : 'start'
    elements.push(`<text x="${number(x)}" y="${number(y)}" fill="${escape(this.fillStyle)}" text-anchor="${anchor}" style="font:${escape(this.font)}">${escape(text)}</text>`)
  },
  save() {
    stack.push({ globalAlpha: this.globalAlpha, lineWidth: this.lineWidth, fillStyle: this.fillStyle, strokeStyle: this.strokeStyle, textAlign: this.textAlign, font: this.font, dash })
  },
  restore() { const state = stack.pop(); dash = state.dash; delete state.dash; Object.assign(this, state) },
}
const palettes = {
  light: { accent: '#6e66b3', real: '#b87828', imaginary: '#168b83', ink: '#555555', background: '#f4f6fb' },
  dark: { accent: '#c4b5fd', real: '#f0c483', imaginary: '#78dcca', ink: '#cccccc', background: '#0f172a' },
}
const colors = palettes[process.argv[4]] || {
  accent: 'var(--math-accent)', real: 'var(--math-real)', imaginary: 'var(--math-imaginary)', ink: 'var(--light-text)', background: 'var(--bg)',
}
const scene = createFourierHat()
scene.cacheBackground(context, colors)
scene.render(context, Number(process.argv[3] || 0) * 2, colors, process.argv[3] === undefined)
const output = process.argv[2] || 'layouts/_partials/decorations/fourier-hat-fallback.html'
const svg = `<svg class="euler-fallback" viewBox="0 0 ${scene.width} ${scene.height}" width="${scene.width}" height="${scene.height}" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" stroke-linecap="round" stroke-linejoin="round">\n${elements.join('\n')}\n</svg>\n`
writeFileSync(output, svg)
console.log(`Fourier hat: ${output}`)
